from collections import deque

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==col:
      seen.add((a,b));q.append((a,b))
   out.append((col,cells))
 return out

def grav(g, d):
 h,w=len(g),len(g[0]); objs=comps(g)
 owner={p:i for i,(_,cs) in enumerate(objs) for p in cs}
 changed=True
 while changed:
  changed=False
  can=[]
  for i,(col,cs) in enumerate(objs):
   ok=True
   for r,c in cs:
    nr,nc=r+d,c
    if not (0<=nr<h): ok=False; break
    j=owner.get((nr,nc))
    if j is not None and j!=i: ok=False; break
   can.append(ok)
  if any(can):
   changed=True
   new=[]
   for i,(col,cs) in enumerate(objs):
    delta=d if can[i] else 0
    new.append((col,[(r+delta,c) for r,c in cs]))
   objs=new; owner={p:i for i,(_,cs) in enumerate(objs) for p in cs}
 out=[[0]*w for _ in range(h)]
 for col,cs in objs:
  for r,c in cs: out[r][c]=col
 return out

